//! Foreign-function interface of the markdown editor core.
//!
//! This crate only adapts [`markdown_editor_core`] to UniFFI so the platform
//! apps can call it; it contains no logic of its own. All unsafe code is
//! generated by UniFFI's macros; handwritten `unsafe` is not allowed.

uniffi::setup_scaffolding!();

/// Reasons why a document cannot be rendered.
#[derive(Debug, Clone, PartialEq, Eq, uniffi::Error)]
pub enum RenderError {
    /// The document is larger than [`max_input_bytes`].
    InputTooLarge {
        /// Size of the document in bytes.
        size: u64,
        /// Maximum size in bytes.
        limit: u64,
    },
    /// The document nests elements deeper than [`max_nesting_depth`].
    NestingTooDeep {
        /// Nesting depth of the document.
        depth: u64,
        /// Maximum nesting depth.
        limit: u64,
    },
    /// The document's syntax tree would have more than [`max_nodes`] nodes.
    TooManyNodes {
        /// Maximum number of nodes.
        limit: u64,
    },
}

impl std::fmt::Display for RenderError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        core_error(self).fmt(f)
    }
}

impl std::error::Error for RenderError {}

/// Renders untrusted Markdown to sanitized HTML. See
/// [`markdown_editor_core::render_html`].
///
/// # Errors
///
/// Returns [`RenderError`] if the document exceeds a resource limit.
#[uniffi::export]
pub fn render_html(markdown: &str) -> Result<String, RenderError> {
    markdown_editor_core::render_html(markdown).map_err(RenderError::from)
}

/// Largest accepted document size in bytes.
#[uniffi::export]
#[must_use]
pub fn max_input_bytes() -> u64 {
    to_u64(markdown_editor_core::MAX_INPUT_BYTES)
}

/// Deepest accepted nesting of Markdown elements.
#[uniffi::export]
#[must_use]
pub fn max_nesting_depth() -> u64 {
    to_u64(markdown_editor_core::MAX_NESTING_DEPTH)
}

/// Largest accepted syntax tree, in nodes.
#[uniffi::export]
#[must_use]
pub fn max_nodes() -> u64 {
    to_u64(markdown_editor_core::MAX_NODES)
}

impl From<markdown_editor_core::RenderError> for RenderError {
    fn from(error: markdown_editor_core::RenderError) -> Self {
        match error {
            markdown_editor_core::RenderError::InputTooLarge { size, limit } => {
                Self::InputTooLarge {
                    size: to_u64(size),
                    limit: to_u64(limit),
                }
            }
            markdown_editor_core::RenderError::NestingTooDeep { depth, limit } => {
                Self::NestingTooDeep {
                    depth: to_u64(depth),
                    limit: to_u64(limit),
                }
            }
            markdown_editor_core::RenderError::TooManyNodes { limit } => Self::TooManyNodes {
                limit: to_u64(limit),
            },
        }
    }
}

/// Converts back for the shared error message.
fn core_error(error: &RenderError) -> markdown_editor_core::RenderError {
    match *error {
        RenderError::InputTooLarge { size, limit } => {
            markdown_editor_core::RenderError::InputTooLarge {
                size: to_usize(size),
                limit: to_usize(limit),
            }
        }
        RenderError::NestingTooDeep { depth, limit } => {
            markdown_editor_core::RenderError::NestingTooDeep {
                depth: to_usize(depth),
                limit: to_usize(limit),
            }
        }
        RenderError::TooManyNodes { limit } => markdown_editor_core::RenderError::TooManyNodes {
            limit: to_usize(limit),
        },
    }
}

fn to_u64(value: usize) -> u64 {
    u64::try_from(value).unwrap_or(u64::MAX)
}

fn to_usize(value: u64) -> usize {
    usize::try_from(value).unwrap_or(usize::MAX)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn renders_like_the_core() {
        let markdown = "# Title\n\n[x](javascript:alert(1)) ![a](https://e.example/a.png)";
        assert_eq!(
            render_html(markdown),
            Ok(markdown_editor_core::render_html(markdown).unwrap())
        );
    }

    #[test]
    fn reports_input_too_large() {
        let markdown = "a".repeat(markdown_editor_core::MAX_INPUT_BYTES + 1);
        assert_eq!(
            render_html(&markdown),
            Err(RenderError::InputTooLarge {
                size: max_input_bytes() + 1,
                limit: max_input_bytes(),
            })
        );
    }

    #[test]
    fn reports_nesting_too_deep() {
        let markdown = format!(
            "{}x",
            ">".repeat(markdown_editor_core::MAX_NESTING_DEPTH + 10)
        );
        assert!(matches!(
            render_html(&markdown),
            Err(RenderError::NestingTooDeep { limit, .. }) if limit == max_nesting_depth()
        ));
    }

    #[test]
    fn reports_too_many_nodes() {
        // Short rows are filled up to the header width.
        let table = "|a".repeat(500) + "|\n" + &"|-".repeat(500) + "|\n" + &"x\n".repeat(1_000);
        let markdown = format!("{table}\n").repeat(10);
        assert_eq!(
            render_html(&markdown),
            Err(RenderError::TooManyNodes { limit: max_nodes() })
        );
    }

    #[test]
    fn limits_match_the_core() {
        assert_eq!(max_input_bytes(), 10 * 1024 * 1024);
        assert_eq!(max_nesting_depth(), 1_000);
        assert_eq!(max_nodes(), 2_000_000);
    }

    #[test]
    fn error_messages_match_the_core() {
        let error = RenderError::NestingTooDeep { depth: 5, limit: 3 };
        assert_eq!(
            error.to_string(),
            "document is nested too deeply to render (depth 5, limit is 3)"
        );
        let error = RenderError::InputTooLarge {
            size: 20,
            limit: 10,
        };
        assert_eq!(
            error.to_string(),
            "document is too large to render (20 bytes, limit is 10 bytes)"
        );
        let error = RenderError::TooManyNodes { limit: 10 };
        assert_eq!(
            error.to_string(),
            "document is too complex to render (more than 10 syntax tree nodes)"
        );
    }

    #[test]
    fn integer_conversions_saturate() {
        assert_eq!(
            to_u64(usize::MAX),
            u64::try_from(usize::MAX).unwrap_or(u64::MAX)
        );
        assert_eq!(
            to_usize(u64::MAX),
            usize::try_from(u64::MAX).unwrap_or(usize::MAX)
        );
    }
}
